import pandas as pd,numpy as np,glob
fs=sorted(glob.glob('train/*.csv'))
def feats(d,tau):
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; Q=d.reactive_power_pu.values; P=d.active_power_pu.values
    Vf=V.copy()
    if tau>0:
        a=1e-3/tau
        for i in range(1,len(V)): Vf[i]=Vf[i-1]+a*(V[i]-Vf[i-1])
    return np.c_[np.ones(len(V)),Vf,Vs,P],Q
for tau in [0,0.02,0.05,0.2]:
    X=[];Y=[]
    for f in fs:
        x,y=feats(pd.read_csv(f),tau); X.append(x);Y.append(y)
    X=np.vstack(X);Y=np.concatenate(Y)
    b=np.linalg.lstsq(X,Y,rcond=None)[0]
    rt=np.sqrt(np.mean((X@b-Y)**2))
    rv=[]
    for f in ['val/A2_val_vref_op2.csv','val/A2_val_load_op1.csv']:
        x,y=feats(pd.read_csv(f),tau); rv.append(round(np.sqrt(np.mean((x@b-y)**2)),5))
    print(tau,np.round(b,4),round(rt,5),rv)
